INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (4,4,'["Quelles sont les étapes clés d''un projet architectural, de la phase de conception jusqu''à la réception des travaux, et quel rôle joue le chef de projet à chacune d''elles ?", "Quels outils ou logiciels de conception architecturale ou de gestion de projet connaissez-vous, et à quel niveau maîtrisez-vous chacun d''eux concrètement ?", "Comment assureriez-vous le suivi technique et administratif d''un chantier tout en respectant les délais, le budget et les normes réglementaires en vigueur au Maroc ?", "Votre diplôme est une Licence générale obtenue à NEXA Digital School en 2024 — quelle est la relation entre cette formation et le métier d''architecte chef de projet pour lequel vous postulez ?", "Sans expérience professionnelle, sur quels projets concrets — académiques, personnels ou bénévoles — pouvez-vous vous appuyer pour démontrer une capacité à piloter un projet de bout en bout ?", "Avez-vous déjà collaboré avec des équipes pluridisciplinaires (ingénieurs, techniciens, maîtres d''ouvrage) dans un contexte de projet, même à titre scolaire ou associatif ?", "Pourquoi postulez-vous à un poste de Chef de projets Architecte alors que votre formation et votre profil semblent orientés vers le numérique — quelle est la logique de ce choix de carrière ?", "Où vous voyez-vous professionnellement dans cinq ans, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous du rôle et des missions de l''Agence de Développement Régional de Fès-Meknès, et quels types de projets l''ADER pilote-t-elle sur le territoire ?", "Quelles sont, selon vous, les principales contraintes spécifiques à la gestion de projets d''architecture dans le secteur public marocain par rapport au secteur privé ?"]','[]','{}','2026-08-27 13:26:10.337150') ON CONFLICT (id) DO NOTHING;